// src/modules/dashboard/Dashboard.js
import React, { useMemo, useState } from "react";
import Sidebar from "../../components/Sidebar";
import Header from "../../components/Header";
import TopCandidates from "../../components/TopCandidates";
import TopJobsProjects from "../../components/TopJobsProjects";
import "./Dashboard.css";
import "../../index.css"; // keep global styles
import { FaUsers, FaDollarSign, FaChartLine, FaUserCheck } from "react-icons/fa";
const API_BASE = "http://127.0.0.1:8000";

const readJson = (key, fallback = []) => {
  try {
    return JSON.parse(localStorage.getItem(key) || JSON.stringify(fallback));
  } catch (e) {
    return fallback;
  }
};

// ======================== COMPANY DASHBOARD ========================


// ======================== COMPANY DASHBOARD ========================
function CompanyDashboard({ jobs, projects, setJobs, setProjects, metrics }) {
  const [showJobForm, setShowJobForm] = useState(false);
  const [showProjectForm, setShowProjectForm] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const [jobForm, setJobForm] = useState({
    job_title: "",
    job_description: "",
    job_type: "",
    required_experience: "",
    required_skills: "",
    work_mode: "",
    salary: "",
    preferred_domain: "",
  });

  const [projectForm, setProjectForm] = useState({
    project_title: "",
    project_description: "",
    project_type: "",
    payment_type: "",
    work_mode: "",
    required_experience: "",
    required_skills: "",
    team_size: "",
    duration: "",
    domain: "",
    salary: "",
  });

  const handleJobSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError("");

    const currentUser = JSON.parse(localStorage.getItem("currentUser") || "{}");
    const user_id = currentUser.user_id;
    if (!user_id) {
      setError("User not found. Please log in again.");
      setLoading(false);
      return;
    }

    try {
      const response = await axios.post(`${API_BASE}/post-job`, {
        user_id,
        ...jobForm,
        salary: jobForm.salary ? parseFloat(jobForm.salary) : null,
      });
      alert("Job posted successfully!");
      setShowJobForm(false);
      setJobForm({
        job_title: "",
        job_description: "",
        job_type: "",
        required_experience: "",
        required_skills: "",
        work_mode: "",
        salary: "",
        preferred_domain: "",
      });
    } catch (err) {
      const msg = err.response?.data?.detail || "Failed to post job.";
      setError(msg);
    } finally {
      setLoading(false);
    }
  };

  const handleProjectSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError("");

    const currentUser = JSON.parse(localStorage.getItem("currentUser") || "{}");
    const user_id = currentUser.user_id;
    if (!user_id) {
      setError("User not found. Please log in again.");
      setLoading(false);
      return;
    }

    try {
      const response = await axios.post(`${API_BASE}/post-project`, {
        user_id,
        ...projectForm,
        team_size: projectForm.team_size ? parseInt(projectForm.team_size) : null,
        salary: projectForm.salary ? parseInt(projectForm.salary) : null,
      });
      alert("Project posted successfully!");
      setShowProjectForm(false);
      setProjectForm({
        project_title: "",
        project_description: "",
        project_type: "",
        payment_type: "",
        work_mode: "",
        required_experience: "",
        required_skills: "",
        team_size: "",
        duration: "",
        domain: "",
        salary: "",
      });
    } catch (err) {
      const msg = err.response?.data?.detail || "Failed to post project.";
      setError(msg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      {/* Action buttons */}
      <div className="dashboard-section-actions" style={{ display: "flex", gap: 12, marginBottom: 18 }}>
        <button className="btn-primary" onClick={() => setShowJobForm(!showJobForm)}>
          Post a Job
        </button>
        <button className="btn-primary" onClick={() => setShowProjectForm(!showProjectForm)}>
          Post a Project
        </button>
      </div>

      {error && <div style={{ color: "#cc3b3b", marginBottom: 12 }}>{error}</div>}

      {/* Job form */}
      {showJobForm && (
        <div className="dashboard-form-card">
          <h3>Post Job</h3>
          <form onSubmit={handleJobSubmit}>
            <input
              required
              placeholder="Job Title"
              value={jobForm.job_title}
              onChange={(e) => setJobForm({ ...jobForm, job_title: e.target.value })}
            />
            <textarea
              required
              placeholder="Job Description"
              value={jobForm.job_description}
              onChange={(e) => setJobForm({ ...jobForm, job_description: e.target.value })}
              rows={4}
              style={{ width: "100%", padding: 10, borderRadius: 8, border: "1px solid #ccc", marginTop: 8 }}
            />
            <select
              required
              value={jobForm.job_type}
              onChange={(e) => setJobForm({ ...jobForm, job_type: e.target.value })}
              style={{ width: "100%", padding: 10, borderRadius: 8, border: "1px solid #ccc", background: "#fff", marginTop: 8 }}
            >
              <option value="">Select Job Type</option>
              <option value="full-time">Full-time</option>
              <option value="part-time">Part-time</option>
              <option value="contract">Contract</option>
            </select>
            <input
              placeholder="Required Experience"
              value={jobForm.required_experience}
              onChange={(e) => setJobForm({ ...jobForm, required_experience: e.target.value })}
            />
            <input
              placeholder="Required Skills (comma-separated)"
              value={jobForm.required_skills}
              onChange={(e) => setJobForm({ ...jobForm, required_skills: e.target.value })}
            />
            <select
              required
              value={jobForm.work_mode}
              onChange={(e) => setJobForm({ ...jobForm, work_mode: e.target.value })}
              style={{ width: "100%", padding: 10, borderRadius: 8, border: "1px solid #ccc", background: "#fff", marginTop: 8 }}
            >
              <option value="">Select Work Mode</option>
              <option value="remote">Remote</option>
              <option value="hybrid">Hybrid</option>
              <option value="onsite">Onsite</option>
            </select>
            <input
              type="number"
              step="0.01"
              placeholder="Salary"
              value={jobForm.salary}
              onChange={(e) => setJobForm({ ...jobForm, salary: e.target.value })}
            />
            <input
              placeholder="Preferred Domain"
              value={jobForm.preferred_domain}
              onChange={(e) => setJobForm({ ...jobForm, preferred_domain: e.target.value })}
            />
            <button type="submit" className="btn-primary" style={{ marginTop: 8 }} disabled={loading}>
              {loading ? "Posting..." : "Post Job"}
            </button>
          </form>
        </div>
      )}

      {/* Project form */}
      {showProjectForm && (
        <div className="dashboard-form-card">
          <h3>Post Project</h3>
          <form onSubmit={handleProjectSubmit}>
            <input
              required
              placeholder="Project Title"
              value={projectForm.project_title}
              onChange={(e) => setProjectForm({ ...projectForm, project_title: e.target.value })}
            />
            <textarea
              required
              placeholder="Project Description"
              value={projectForm.project_description}
              onChange={(e) => setProjectForm({ ...projectForm, project_description: e.target.value })}
              rows={4}
              style={{ width: "100%", padding: 10, borderRadius: 8, border: "1px solid #ccc", marginTop: 8 }}
            />
            <select
              required
              value={projectForm.project_type}
              onChange={(e) => setProjectForm({ ...projectForm, project_type: e.target.value })}
